/*! Bootstrap Bundle v5.2.3 (local minimal implementation)
   Provides minimal Dropdown and Collapse behaviors required by this template.
   Not a full Bootstrap build; no Popper, no positioning logic, no animations.
*/
(function(){
  if (typeof window==='undefined') return;
  var doc=document, w=window;
  function on(el, ev, fn, opts){ el.addEventListener(ev, fn, opts||false); }
  function qs(sel, ctx){ return (ctx||doc).querySelector(sel); }
  function qsa(sel, ctx){ return Array.prototype.slice.call((ctx||doc).querySelectorAll(sel)); }
  function getTarget(trigger){ var sel=trigger.getAttribute('data-bs-target')||trigger.getAttribute('href'); if(!sel) return null; try{ return qs(sel.trim()); }catch(e){ return null; } }
  function closest(el, sel){ while(el && el.nodeType===1){ if(el.matches(sel)) return el; el=el.parentElement; } return null; }
  function toggleClass(el, cls, state){ if(!el) return; if(state===undefined){ el.classList.toggle(cls); } else { state?el.classList.add(cls):el.classList.remove(cls); } }
  function hideAllDropdowns(exceptMenu){ qsa('.dropdown-menu.show').forEach(function(m){ if(m!==exceptMenu){ toggleClass(m,'show',false); var parent=closest(m,'.dropdown, .dropup, .dropstart, .dropend')||m.parentElement; if(parent) toggleClass(parent,'show',false); var t=qs('[data-bs-toggle="dropdown"][aria-expanded="true"]', parent); if(t){ t.setAttribute('aria-expanded','false'); } } }); }

  // Dropdown minimal
  function setupDropdowns(){
    on(doc,'click',function(e){
      var t=e.target;
      var toggleEl = t.closest('[data-bs-toggle="dropdown"]');
      if(toggleEl){
        e.preventDefault();
        var parent = closest(toggleEl,'.dropdown, .dropup, .dropstart, .dropend') || toggleEl.parentElement;
        var menu = parent? qs('.dropdown-menu', parent): null;
        if(!menu) return;
        var isOpen = menu.classList.contains('show');
        hideAllDropdowns(menu);
        if(!isOpen){
          toggleClass(parent,'show',true);
          toggleClass(menu,'show',true);
          toggleEl.setAttribute('aria-expanded','true');
        } else {
          toggleClass(menu,'show',false);
          toggleClass(parent,'show',false);
          toggleEl.setAttribute('aria-expanded','false');
        }
        return;
      }
      // click outside -> close all
      if(!closest(t,'.dropdown-menu') && !closest(t,'[data-bs-toggle="dropdown"]')){
        hideAllDropdowns();
      }
    });
    on(doc,'keydown',function(e){ if(e.key==='Escape'){ hideAllDropdowns(); } });
  }

  // Collapse minimal
  function closeSiblingsIfAccordion(target){
    var parentSel = target.getAttribute('data-bs-parent');
    if(!parentSel) return;
    var parent = qs(parentSel);
    if(!parent) return;
    qsa('.collapse.show', parent).forEach(function(openEl){ if(openEl!==target){ toggleClass(openEl,'show',false); var trig = qs('[data-bs-toggle="collapse"][data-bs-target="#'+openEl.id+'"], [data-bs-toggle="collapse"][href="#'+openEl.id+'"]'); if(trig){ trig.classList.add('collapsed'); trig.setAttribute('aria-expanded','false'); } } });
  }
  function setupCollapses(){
    on(doc,'click',function(e){
      var t=e.target.closest('[data-bs-toggle="collapse"]');
      if(!t) return;
      var target = getTarget(t);
      if(!target) return;
      e.preventDefault();
      var willOpen = !target.classList.contains('show');
      if(willOpen){ closeSiblingsIfAccordion(target); }
      toggleClass(target,'show',willOpen);
      // update trigger state
      toggleClass(t,'collapsed',!willOpen);
      t.setAttribute('aria-expanded', willOpen? 'true':'false');
    });
  }

  // Public API stubs (for compatibility)
  w.bootstrap = w.bootstrap || {};
  function api(name){ return function(element){ return { show:function(){}, hide:function(){}, toggle:function(){}, dispose:function(){} }; }; }
  ['Alert','Button','Carousel','Collapse','Dropdown','Modal','Offcanvas','Popover','ScrollSpy','Tab','Toast','Tooltip'].forEach(function(n){ w.bootstrap[n]=api(n); });

  on(doc,'DOMContentLoaded',function(){ setupDropdowns(); setupCollapses(); });
})();
